#!/usr/bin/env node
// Fails when a Tailwind utility that targets a physical inline side (left/right) appears in
// source files. MAQDAR mirrors for Arabic, so only logical utilities are allowed:
// ms-/me-, ps-/pe-, inset-s-/inset-e-, rounded-s-/rounded-e-, border-s/border-e, text-start/end.
// Files under components/ui are generated by shadcn with `rtl: true` and are skipped, as are
// tests. Classes under an rtl:/ltr:/data-[side=…] variant are intentional and allowed.
//
// Usage: node scripts/check-logical-utilities.mjs <dir-or-file...>

import { readdirSync, readFileSync, statSync } from 'node:fs'
import { join, relative, resolve, sep } from 'node:path'
import { pathToFileURL } from 'node:url'

const SOURCE_FILE = /\.(?:tsx?|jsx?|mjs|css)$/
const SKIPPED_PATH =
  /(?:^|[\\/])(?:node_modules|\.next|components[\\/]ui)(?:[\\/]|$)|\.test\.[cm]?[jt]sx?$|\.spec\.[cm]?[jt]sx?$/

// Utility bases that take a value (`pl-4`, `-left-2`, `border-r-2`).
const PHYSICAL_PREFIXES = [
  'ml',
  'mr',
  'pl',
  'pr',
  'left',
  'right',
  'inset-l',
  'inset-r',
  'scroll-ml',
  'scroll-mr',
  'scroll-pl',
  'scroll-pr',
  'rounded-l',
  'rounded-r',
  'rounded-tl',
  'rounded-tr',
  'rounded-bl',
  'rounded-br',
  'border-l',
  'border-r',
  'slide-in-from-left',
  'slide-in-from-right',
  'slide-out-to-left',
  'slide-out-to-right',
]
// Utilities that are complete on their own.
const PHYSICAL_EXACT = [
  'text-left',
  'text-right',
  'float-left',
  'float-right',
  'clear-left',
  'clear-right',
  'origin-left',
  'origin-right',
  'origin-top-left',
  'origin-top-right',
  'origin-bottom-left',
  'origin-bottom-right',
  'rounded-l',
  'rounded-r',
  'rounded-tl',
  'rounded-tr',
  'rounded-bl',
  'rounded-br',
  'border-l',
  'border-r',
]
const PHYSICAL = new RegExp(
  `^-?(?:(?:${PHYSICAL_PREFIXES.join('|')})-.+|${PHYSICAL_EXACT.join('|')})$`,
)
const INTENTIONAL_VARIANT = /^(?:rtl|ltr)$|data-\[side=(?:left|right)\]/

/** Splits `md:hover:data-[side=left]:pl-2` into variants and the base utility. */
export function splitVariants(token) {
  const parts = []
  let depth = 0
  let current = ''
  for (const char of token) {
    if (char === '[' || char === '(') depth++
    if (char === ']' || char === ')') depth--
    if (char === ':' && depth === 0) {
      parts.push(current)
      current = ''
    } else {
      current += char
    }
  }
  parts.push(current)
  return { variants: parts.slice(0, -1), base: parts.at(-1) ?? '' }
}

function stripComments(text) {
  return text.replace(/\/\*[\s\S]*?\*\//g, '').replace(/(^|[^:])\/\/.*$/gm, '$1')
}

/** Returns `{ line, token }` for every physical utility found in `text`. */
export function findViolations(text, { css = false } = {}) {
  const violations = []
  const lines = stripComments(text).split(/\r?\n/)
  lines.forEach((line, index) => {
    if (css && !line.includes('@apply')) return
    if (/^\s*(?:import|export)\b.*\bfrom\b/.test(line)) return
    for (const token of line.split(/[\s"'`{}(),;<>]+/)) {
      if (!token || token.includes('://')) continue
      const { variants, base } = splitVariants(token)
      if (!PHYSICAL.test(base)) continue
      if (variants.some((variant) => INTENTIONAL_VARIANT.test(variant))) continue
      violations.push({ line: index + 1, token })
    }
  })
  return violations
}

function* walk(path) {
  const stats = statSync(path)
  if (stats.isDirectory()) {
    for (const entry of readdirSync(path)) yield* walk(join(path, entry))
  } else if (SOURCE_FILE.test(path) && !SKIPPED_PATH.test(path)) {
    yield path
  }
}

function main(targets) {
  let total = 0
  for (const target of targets.map((t) => resolve(t))) {
    for (const file of walk(target)) {
      const text = readFileSync(file, 'utf8')
      const violations = findViolations(text, { css: file.endsWith('.css') })
      for (const { line, token } of violations) {
        total++
        console.error(`${relative(process.cwd(), file).split(sep).join('/')}:${line}: ${token}`)
      }
    }
  }
  if (total > 0) {
    console.error(
      `\n${total} physical utility class${total === 1 ? '' : 'es'} found. ` +
        'Use logical utilities (ms-/me-, ps-/pe-, inset-s-/inset-e-, text-start/end, …).',
    )
    process.exit(1)
  }
  console.log('No physical left/right utilities found.')
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const targets = process.argv.slice(2)
  if (targets.length === 0) {
    console.error('Usage: node scripts/check-logical-utilities.mjs <dir-or-file...>')
    process.exit(2)
  }
  main(targets)
}
